"use client";
import React, { useRef, useEffect } from "react";
import ChannelCard from "./ChannelCard";

function CarouselSection({ title, channels, onExplore, isRelated = false }) {
    const wrapperRef = useRef(null);
    const scrollRef = useRef(null);
    const btnLeftRef = useRef(null);
    const btnRightRef = useRef(null);

    const updateArrows = () => {
        const grid = scrollRef.current;
        if (!grid) return;
        if (btnLeftRef.current) {
            if (grid.scrollLeft <= 5) {
                btnLeftRef.current.classList.add("arrow-disabled");
            } else {
                btnLeftRef.current.classList.remove("arrow-disabled");
            }
        }
        if (btnRightRef.current) {
            if (Math.ceil(grid.scrollLeft + grid.clientWidth) >= grid.scrollWidth - 5) {
                btnRightRef.current.classList.add("arrow-disabled");
            } else {
                btnRightRef.current.classList.remove("arrow-disabled");
            }
        }
    };

    const isVodSection = channels.some(c => Boolean(c.isVod || c.vodType));

    useEffect(() => {
        const wrapper = wrapperRef.current;
        if (!wrapper) return;

        const updateCardWidth = () => {
            const w = wrapper.clientWidth;
            if (w > 0) {
                let numCards = isVodSection ? 6 : 5;
                if (window.innerWidth <= 600) {
                    numCards = isVodSection ? 3 : 2;
                } else if (window.innerWidth <= 900) {
                    numCards = isVodSection ? 4 : 3;
                } else if (window.innerWidth <= 1200) {
                    numCards = isVodSection ? 5 : 4;
                }
                const gapCount = numCards - 1;
                const totalGapSpace = gapCount * 16;
                const cardW = Math.floor((w - totalGapSpace) / numCards);
                wrapper.style.setProperty("--card-width", `${cardW}px`);
                wrapper.dataset.cardsPerView = numCards;
                updateArrows();
            }
        };

        const resizeObserver = new ResizeObserver(updateCardWidth);
        resizeObserver.observe(wrapper);
        updateCardWidth();

        let ticking = false;
        const handleScroll = () => {
            if (!ticking) {
                requestAnimationFrame(() => {
                    updateArrows();
                    ticking = false;
                });
                ticking = true;
            }
        };

        const grid = scrollRef.current;
        if (grid) {
            grid.addEventListener("scroll", handleScroll, { passive: true });
        }

        return () => {
            resizeObserver.disconnect();
            if (grid) {
                grid.removeEventListener("scroll", handleScroll);
            }
        };
    }, []);

    const scroll = (direction) => {
        const grid = scrollRef.current;
        const wrapper = wrapperRef.current;
        if (!grid || !wrapper) return;

        const numCards = parseInt(wrapper.dataset.cardsPerView, 10) || 5;
        const cardW = parseFloat(wrapper.style.getPropertyValue("--card-width")) || 240;
        const pageStep = numCards * (cardW + 16);
        const maxScroll = grid.scrollWidth - grid.clientWidth;

        let targetLeft;
        if (direction === "left") {
            const prevPage = Math.floor((grid.scrollLeft - 5) / pageStep);
            targetLeft = Math.max(0, prevPage * pageStep);
        } else {
            const nextPage = Math.ceil((grid.scrollLeft + 5) / pageStep);
            const nextTarget = nextPage * pageStep;
            targetLeft = nextTarget >= maxScroll - 20 ? maxScroll : nextTarget;
        }

        grid.scrollTo({ left: targetLeft, behavior: "smooth" });
    };

    if (!channels || channels.length === 0) return null;

    const count = channels.length;
    const isTestJsonGroup = channels.some(c => c.isTestJson || (c.group && c.group.toUpperCase().replace(/\s+/g, "").includes("EVENTI")));

    let badgeLabel;
    if (isVodSection) {
        const firstVodType = channels[0]?.vodType;
        const firstGroup = (channels[0]?.group || "").toLowerCase();
        const isTvSection = firstVodType === "tv" || firstGroup.includes("serie");
        badgeLabel = isTvSection
            ? `${count} serie TV`
            : `${count} film`;
    } else if (isTestJsonGroup) {
        badgeLabel = `${count} ${count === 1 ? "evento" : "eventi"}`;
    } else {
        badgeLabel = `${count} ${count === 1 ? "canale" : "canali"}`;
    }

    return (
        <div className={`${isRelated ? "" : "home-section"} ${isVodSection ? "vod-carousel-section" : ""}`}>
            <div className="category-header-container" style={isRelated ? { marginBottom: "16px", marginTop: "28px" } : {}}>
                <div className="category-header-left">
                    {isRelated ? (
                        <h2 className="related-title" style={{ margin: 0 }}>{title}</h2>
                    ) : (
                        <h2>{title}</h2>
                    )}
                    <span className="category-count-badge">
                        {badgeLabel}
                    </span>
                </div>
                <div className="category-header-right" style={{ display: "flex", alignItems: "center", gap: "20px" }}>
                    {!isRelated && onExplore && (
                        <button
                            type="button"
                            className="explore-all-btn"
                            onClick={() => onExplore(title, channels)}
                        >
                            Esplora tutti
                            <span className="material-symbols-rounded" style={{ fontSize: "1.1rem", marginLeft: "2px" }}>
                                arrow_forward
                            </span>
                        </button>
                    )}
                </div>
            </div>

            <div className="carousel-wrapper" ref={wrapperRef}>
                <button
                    ref={btnLeftRef}
                    type="button"
                    className="carousel-btn carousel-btn--left"
                    onClick={() => scroll("left")}
                    aria-label="Precedente"
                >
                    <span className="material-symbols-rounded">chevron_left</span>
                </button>

                <div className="home-carousel" ref={scrollRef}>
                    {channels.map((ch, idx) => (
                        <ChannelCard
                            key={ch.id || (ch.title + idx)}
                            channel={ch}
                            categoryName={title}
                            priority={idx < 5}
                        />
                    ))}
                </div>

                <button
                    ref={btnRightRef}
                    type="button"
                    className="carousel-btn carousel-btn--right"
                    onClick={() => scroll("right")}
                    aria-label="Successivo"
                >
                    <span className="material-symbols-rounded">chevron_right</span>
                </button>
            </div>
        </div>
    );
}

export default React.memo(CarouselSection);
